 V('meeting recap=resumo de reunião|time difference=diferença de fuso|bilingual meeting=reunião bilíngue|next steps=próximos passos|team alignment=alinhamento da equipe|launch plan=plano de lançamento|summary e-mail=e-mail-resumo|unclear point=ponto obscuro|short call=ligação curta|follow-up note=nota de acompanhamento|agreed action=ação combinada|meeting minutes=ata de reunião|call schedule=agenda de ligações|language switch=troca de idioma|interpreter support=apoio de intérprete|slide language=idioma dos slides|clarification request=pedido de esclarecimento|shared document=documento compartilhado|time zone=fuso horário|working overlap=sobreposição de horário|response time=tempo de resposta|decision log=registro de decisões|action owner=responsável pela ação|project handover=passagem de projeto|stakeholder email=e-mail a partes interessadas|launch readiness=prontidão para lançamento|email tone=tom de e-mail|polite reminder=lembrete educado'),
 ('Global call',[('Ana','Having reviewed the notes, I realize some points were unclear.','Tendo revisado as anotações, percebo que alguns pontos ficaram obscuros.'),('Leo','Not wanting to create confusion, you sent a summary.','Não querendo criar confusão, você enviou um resumo.'),('Ana','Held in two languages, the meeting needed patience.','Realizada em dois idiomas, a reunião exigiu paciência.'),('Leo','With everyone aligned, we can launch.','Com todos alinhados, podemos lançar.')]),
 [('Use having + participle.','Use.','Having read it, I agree.'),('Use not wanting to.','Use.','Not wanting to be late, I left early.'),('Use with + object + participle.','Use.','With the work done, we left.')],
